var diffToMonday = (day + 6) % 7;  // hur många dagar bakåt till måndag
base.setDate(base.getDate() - diffToMonday);
var baseMs = base.getTime();       // måndag 00:00 i ms

// Konvertera [{x,y} ..] eller [y,..] -> [{x:timestamp,y},..] per serie
